function parseLedger(markdown) {
  // Only the canonical ledger is authoritative.
  // The archive may contain decoy headings like "## Transaction Ledger (working copy)".
  const headerRe = /^## Transaction Ledger\s*$/m;
  const m = markdown.match(headerRe);
  if (!m) return [];

  const slice = markdown.slice(m.index);
  const blocks = slice.split(/^### /m).slice(1);

  const byId = new Map();

  for (const block of blocks) {
    const lines = block.split("\n");
    const transactionId = lines[0].trim();
    if (!transactionId.startsWith("TXN-")) continue;

    const row = { transaction_id: transactionId, provisional: false };

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("amount:")) {
        row.amount = Number(trimmed.split(":")[1].trim());
      } else if (trimmed.startsWith("owner:")) {
        row.owner = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("status:")) {
        row.status = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("date:")) {
        row.date = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("provisional:")) {
        row.provisional = trimmed.split(":")[1].trim().toLowerCase() === "true";
      }
    }

    const existing = byId.get(transactionId);
    if (!existing) {
      byId.set(transactionId, row);
      continue;
    }

    // Prefer non-provisional over provisional; otherwise take the later occurrence.
    if (existing.provisional && !row.provisional) byId.set(transactionId, row);
    else if (existing.provisional === row.provisional) byId.set(transactionId, row);
  }

  return [...byId.values()];
}

module.exports = { parseLedger };
EOF

