const { sortByTransactionId } = require("../utils/sort");
const { applyExceptionReasons } = require("./exceptions");

const STATUS_ORDER = {
  pending: 0,
  approved: 1,
  rejected: 2,
  reversed: 3,
};

function reconcileTransactions(parsed) {
  // Base rows from canonical ledger
  const byId = new Map();
  for (const row of parsed.ledger) byId.set(row.transaction_id, { ...row });

  // Meeting amendments: signed only
  for (const amend of parsed.meetings) {
    if (!amend.signed) continue;
    const target = byId.get(amend.transaction_id);
    if (!target) continue;
    if (amend.owner) target.owner = amend.owner;
  }

  // Compliance mail can change status only from compliance@ senders.
  for (const email of parsed.emails) {
    if (!String(email.from_addr).includes("compliance@")) continue;
    const target = byId.get(email.transaction_id);
    if (!target) continue;

    const current = String(target.status).toLowerCase();
    const incoming = String(email.status).toLowerCase();
    if (incoming in STATUS_ORDER && current in STATUS_ORDER) {
      if (STATUS_ORDER[incoming] > STATUS_ORDER[current]) target.status = incoming;
    }
  }

  // Brief 09: compliance_hold uses the date *before* correction notices.
  const preCorrectionDateByTxn = new Map();
  for (const [id, row] of byId.entries()) preCorrectionDateByTxn.set(id, row.date);

  const complianceHoldByTxn = new Map();
  for (const email of parsed.emails) {
    if (!String(email.from_addr).includes("compliance@")) continue;
    if (String(email.status).toLowerCase() !== "compliance_hold") continue;
    if (!email.sent) continue;

    const baseDate = preCorrectionDateByTxn.get(email.transaction_id);
    if (!baseDate) continue;

    if (email.sent > baseDate) complianceHoldByTxn.set(email.transaction_id, true);
  }

  // Apply corrections deterministically
  const sortedNotices = [...parsed.corrections].sort((a, b) => {
    const ed = String(a.effective).localeCompare(String(b.effective));
    if (ed !== 0) return ed;
    return String(a.notice_id).localeCompare(String(b.notice_id));
  });

  const applied = [];
  for (const notice of sortedNotices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    let previous;
    if (notice.field === "owner") {
      previous = String(target.owner ?? "");
      target.owner = notice.value;
    } else if (notice.field === "status") {
      previous = String(target.status ?? "");
      target.status = String(notice.value).toLowerCase();
    } else if (notice.field === "date") {
      previous = String(target.date ?? "");
      target.date = notice.value;
    } else {
      continue;
    }

    applied.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: previous,
      new_value: notice.value,
      effective: notice.effective,
    });
  }

  // Winning correction = last applied for a given (txn, field)
  const winningByKey = new Map();
  for (const r of applied) winningByKey.set(`${r.transaction_id}::${r.field}`, r);
  const report = [...winningByKey.values()].sort((a, b) =>
    String(a.notice_id).localeCompare(String(b.notice_id)),
  );

  const winningStatusCorrectionByTxn = new Set(
    report.filter((r) => r.field === "status").map((r) => r.transaction_id),
  );

  let items = sortByTransactionId(
    [...byId.values()].map((row) => ({
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      effective_date: row.date,
      amount_usd: Number(row.amount),
      exception_reason: null,
    })),
  );

  items = applyExceptionReasons(items, {
    policyExceptions: parsed.policyExceptions,
    complianceHoldByTxn,
    winningStatusCorrectionByTxn,
  });

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
EOF
